-- Shared authored Kessler example. No invented people, API jobs, expenses or credit grants.
-- Applying again verifies prepared rows and leaves public continuations and balances untouched.
do $kessler$
declare r public.pilot_rooms; m public.pilot_moments; expected public.pilot_moments;
  seeds jsonb := $seed$[{"id":"15000000-0000-4000-8000-000000000001","room_id":"kessler-ward","parent_id":null,"maker_id":null,"maker_label":"Prepared story","title":"Lights out in Kessler Ward","panels":[{"imageUrl":"/art/night-shift-neon.webp#frame=0","caption":"The grid drops at midnight. Every tower in Kessler Ward goes dark except the red emergency strips, and the trains stop where they stand."},{"imageUrl":"/art/night-shift-neon.webp#frame=1","caption":"Odo presses an insulated case into Mika's hands. ‘Mrs. Ito, floor eighty-one. Her insulin runs out at dawn. No lifts tonight.’"}],"source_kind":"fixture","created_at":"2026-10-14T18:00:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000002","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000001","maker_id":null,"maker_label":"Prepared story","title":"The billboard blinks back","panels":[{"imageUrl":"/art/night-shift-neon.webp#frame=2","caption":"A dead billboard flickers awake for one breath. A small bird of cyan light traces a path across the rooftops, along the one cable line that still carries power."}],"source_kind":"fixture","created_at":"2026-10-14T18:01:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000003","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000002","maker_id":null,"maker_label":"Prepared story","title":"Rei on the dish","panels":[{"imageUrl":"/art/night-shift-neon.webp#frame=3","caption":"The bird's path ends at a cable bridge. Rei waves from the satellite dish on the far tower, headphones on, calling out every loose rung over the radio."}],"source_kind":"fixture","created_at":"2026-10-14T18:02:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000004","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000003","maker_id":null,"maker_label":"Prepared story","title":"The bridge goes dark","panels":[{"imageUrl":"/art/night-shift-neon-2.webp#frame=0","caption":"Halfway across, the billboard's power fails. The bird flares once and breaks into sparks, and Mika is left holding the chain in the dark and the wind."}],"source_kind":"fixture","created_at":"2026-10-14T18:03:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000005","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000004","maker_id":null,"maker_label":"Prepared story","title":"A tower full of lights","panels":[{"imageUrl":"/art/night-shift-neon-2.webp#frame=1","caption":"Rei gets on every channel in the next tower. Window by window, people hold up their phones until the whole tower shines, and Mika can see every rung."}],"source_kind":"fixture","created_at":"2026-10-14T18:04:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000006","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000005","maker_id":null,"maker_label":"Prepared story","title":"In through the window","panels":[{"imageUrl":"/art/night-shift-neon-2.webp#frame=2","caption":"At first light Mika swings in through Mrs. Ito's kitchen window on floor eighty-one. Mrs. Ito takes the case in both hands. ‘You came the long way.’"}],"source_kind":"fixture","created_at":"2026-10-14T18:05:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000007","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000001","maker_id":null,"maker_label":"Prepared story","title":"Eighty-one floors","panels":[{"imageUrl":"/art/night-shift-neon.webp#frame=4","caption":"No lift, no light. Mika takes the stairwell two steps at a time, her flashlight the only thing moving in the tower."}],"source_kind":"fixture","created_at":"2026-10-14T18:06:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000008","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000007","maker_id":null,"maker_label":"Prepared story","title":"Floor forty","panels":[{"imageUrl":"/art/night-shift-neon-2.webp#frame=3","caption":"On the fortieth landing her legs give out. A door opens and Kenji from 40C crouches beside her with a bottle of water. ‘Who's it for?’"}],"source_kind":"fixture","created_at":"2026-10-14T18:07:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000009","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000008","maker_id":null,"maker_label":"Prepared story","title":"Every door left open","panels":[{"imageUrl":"/art/night-shift-neon.webp#frame=5","caption":"Kenji knocks on the next door, and that neighbor knocks on the next. Doors open on every landing, phones light the stairs, and a bird of light flies ahead to show the way."}],"source_kind":"fixture","created_at":"2026-10-14T18:08:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000010","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000009","maker_id":null,"maker_label":"Prepared story","title":"Hand to hand","panels":[{"imageUrl":"/art/night-shift-neon-2.webp#frame=4","caption":"The neighbors form a chain, one person to a step. The case goes up hand to hand, floor after floor, while Mika gets her breath back and follows."}],"source_kind":"fixture","created_at":"2026-10-14T18:09:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null},{"id":"15000000-0000-4000-8000-000000000011","room_id":"kessler-ward","parent_id":"15000000-0000-4000-8000-000000000010","maker_id":null,"maker_label":"Prepared story","title":"Dawn on eighty-one","panels":[{"imageUrl":"/art/night-shift-neon-2.webp#frame=5","caption":"The case reaches Mrs. Ito as the sun comes up and the city's lights blink back on. The bird of light settles on her windowsill, then fades into the morning."}],"source_kind":"fixture","created_at":"2026-10-14T18:10:00.000Z","source_idea_body":null,"source_idea_id":null,"source_idea_label":null}]$seed$::jsonb;
begin
  insert into public.pilot_rooms(id,title,description,is_open,is_listed)
    values('kessler-ward','Kessler Ward',$description$A blackout, an insulin case and eighty-one floors before dawn. Choose a branch and write what happens next.$description$,true,true)
    on conflict(id) do nothing;
  select * into strict r from public.pilot_rooms where id='kessler-ward' for update;
  if r.title<>'Kessler Ward' or r.description<>$description$A blackout, an insulin case and eighty-one floors before dawn. Choose a branch and write what happens next.$description$ or r.owner_id is not null or r.template_id is not null or not r.is_open or not r.is_listed then
    raise exception 'Kessler Ward room ID already has different content; no existing story was replaced';
  end if;
  for expected in select * from jsonb_populate_recordset(null::public.pilot_moments,seeds) loop
    insert into public.pilot_moments(id,room_id,parent_id,maker_id,maker_label,title,panels,source_kind,created_at)
      values(expected.id,expected.room_id,expected.parent_id,null,expected.maker_label,expected.title,expected.panels,'fixture',expected.created_at)
      on conflict(id) do nothing;
    select * into strict m from public.pilot_moments where id=expected.id;
    if m.room_id<>expected.room_id or m.parent_id is distinct from expected.parent_id or m.maker_id is not null or m.maker_label<>expected.maker_label or m.title<>expected.title or m.panels<>expected.panels or m.source_kind<>'fixture' or m.created_at<>expected.created_at or m.source_idea_id is not null then
      raise exception 'A prepared Kessler moment conflicts with existing work; nothing was overwritten';
    end if;
  end loop;
  insert into public.pilot_room_capacity(room_id,delivery_limit,guest_attempt_limit)
    values('kessler-ward',0,3) on conflict(room_id) do nothing;
  -- Display-only rename: retain the old room ID, authorship, agent history and payments.
  update public.pilot_rooms set title='The Uncharted Star',
    description='A lighthouse finds an uncharted star. Follow its light, or write another way through the harbor.'
    where id='night-shift' and lower(btrim(title)) in ('night shift','the night shift');
end;
$kessler$;
